// A voice clip: VOICE<xas>.XAS channel `channel` (of 16), sectors
// channel + 16*c for c in [start, end). 37.8 kHz mono 4-bit CD-XA.
// A P<row>_<id> name is a PS1-only clip for one voice id (voice table
// row, id in hex), which voice_load_and_play looks for before the name.
struct Ps1VoiceEntry {
    const char* pcName;  // Voice/<pcName>.wav
    uint8_t xas;         // 1..5
    uint8_t channel;
    uint16_t start;
    uint16_t end;
};

