// A BGM channel: SOUND/SEP<group>.HSB, sequence track `track`
// (g_BgmNameTable[group][track]). `pcRms` is the PC file's RMS in
// 16-bit units: the PC normalised every BGM on its own (0.66..3.5x the
// PS1 render's level) and its engine volumes assume those levels, so the
// render is levelled to it. 0 = no PC file.
struct Ps1BgmEntry {
    const char* pcName;  // Sound/<pcName>.wav
    uint8_t group;
    uint8_t track;
    uint16_t pcRms;
};

